input_script:
var boardRequest = input.query || input || {};
var boardProjects = Array.isArray(boardRequest.projects) ? boardRequest.projects : (boardRequest.projects ? [boardRequest.projects] : []);
var boardScopes = [];
for (var bs = 0; bs < boardProjects.length; bs++) {
  var bp = boardProjects[bs];
  if (!bp) continue;
  var bk = typeof bp === 'object' ? String(bp.jiraproject || '').trim() : '';
  var bn = typeof bp === 'string' ? bp.trim() : String(bp.projectname || '').trim();
  if (!bk && !bn) continue;
  boardScopes.push({project_key: bk, project_name: bn,
    board_id: typeof bp === 'object' ? String(bp.boardid || '').trim() : '',
    connection_id: String((typeof bp === 'object' && bp.connectionid) || boardRequest.connectionid || '').trim()});
}

var scopeRequest = input.query || input || {};
var scopeProjects = Array.isArray(scopeRequest.projects) ? scopeRequest.projects : (scopeRequest.projects ? [scopeRequest.projects] : []);
var projectKeys = [];
for (var si = 0; si < scopeProjects.length; si++) {
  var sp = scopeProjects[si];
  var sk = typeof sp === 'object' && sp !== null ? String(sp.jiraproject || '').trim() : '';
  if (sk && projectKeys.indexOf(sk) < 0) projectKeys.push(sk);
}
var hasIssueScope = 0;
for (var scopeIndex = 0; scopeIndex < scopeProjects.length; scopeIndex++) {
  var scopeProject = scopeProjects[scopeIndex];
  if (typeof scopeProject === 'string' && scopeProject.trim()) hasIssueScope = 1;
  if (scopeProject && typeof scopeProject === 'object' &&
      (String(scopeProject.projectname || '').trim() || String(scopeProject.jiraproject || '').trim())) hasIssueScope = 1;
}
if (projectKeys.length === 0) projectKeys = ['__NONE__'];

var from = input.from;
var to = input.to;
var projectNames = [];
for (var pi = 0; pi < scopeProjects.length; pi++) {
  var project = scopeProjects[pi];
  var projectName = typeof project === 'string' ? project.trim() : String(project.projectname || '').trim();
  if (projectName) projectNames.push(projectName);
}
if (projectNames.length === 0) projectNames = ['__NONE__'];

var diffSeconds = Math.abs(to - from);
var diffDays = Math.floor(diffSeconds / (60 * 60 * 24));
var compareFrom = 0;
var compareTo = 0;
var hasCompare = 0;

if (diffDays <= 30) {
  compareTo = from;
  compareFrom = compareTo - Math.abs(to - from);
  hasCompare = 1;
}

var hasUserwhitelist = 0;
var userwhitelist = ["_"];
if (input.userwhitelist && input.userwhitelist.length > 0) {
  hasUserwhitelist = 1;
  userwhitelist = input.userwhitelist;
}

({
  boardScopes: JSON.stringify(boardScopes),
  projectKeys: projectKeys,
  hasIssueScope: hasIssueScope,
  from: from,
  to: to,
  projectNames: projectNames,
  compareFrom: compareFrom,
  compareTo: compareTo,
  hasCompare: hasCompare,
  hasUserwhitelist: hasUserwhitelist,
  userwhitelist: userwhitelist
})

output_script:
function calculateMedian(arr) {
  if (arr.length === 0) return 0;
  var sorted = arr.slice().sort(function(a, b) { return a - b; });
  var mid = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 0) {
    return (sorted[mid - 1] + sorted[mid]) / 2;
  }
  return sorted[mid];
}

function calcKPIs(issueList, from, to) {
  var startDate = from ? new Date(from * 1000) : new Date(0);
  var endDate = to ? new Date(to * 1000) : new Date();

  var openIssues = 0;
  var resolvedIssues = [];
  var i, issue;

  for (i = 0; i < issueList.length; i++) {
    issue = issueList[i];
    if (issue.status === "TODO" || issue.status === "IN_PROGRESS") {
      openIssues++;
    } else if (issue.resolution_date && issue.created_date) {
      resolvedIssues.push(issue);
    }
  }

  var totalResolved = resolvedIssues.length;

  var resolutionTimes = [];
  for (i = 0; i < resolvedIssues.length; i++) {
    issue = resolvedIssues[i];
    var createdAt = new Date(issue.created_date);
    if (isNaN(createdAt.getTime())) continue;
    var resolvedAt = new Date(issue.resolution_date);
    if (isNaN(resolvedAt.getTime())) continue;
    var hours = (resolvedAt - createdAt) / (1000 * 60 * 60);
    if (hours >= 0) resolutionTimes.push(hours);
  }

  var medianResolutionTime = calculateMedian(resolutionTimes);

  var totalStoryPoints = 0;
  for (i = 0; i < resolvedIssues.length; i++) {
    var points = parseFloat(resolvedIssues[i].story_point);
    if (!isNaN(points)) totalStoryPoints += points;
  }

  var createdIssues = 0;
  if (from || to) {
    for (i = 0; i < issueList.length; i++) {
      var createdDate = new Date(issueList[i].created_date);
      if (isNaN(createdDate.getTime())) continue;
      if (createdDate >= startDate && createdDate <= endDate) {
        createdIssues++;
      }
    }
  } else {
    for (i = 0; i < issueList.length; i++) {
      if (issueList[i].created_date) createdIssues++;
    }
  }

  return {
    totalResolved: totalResolved,
    openIssues: openIssues,
    createdIssues: createdIssues,
    medianResolutionTime: medianResolutionTime,
    totalStoryPoints: totalStoryPoints
  };
}

var issueRows = results.issues || [];
var compareRows = results.compareissues || [];

var queryFrom = issueRows.length > 0 ? issueRows[0].query_from : 0;
var queryTo = issueRows.length > 0 ? issueRows[0].query_to : 0;

var current = calcKPIs(issueRows, queryFrom, queryTo);

var resolved_explain = "";
var created_explain = "";
var resolution_time_explain = "";
var story_points_explain = "";

if (compareRows.length > 0) {
  var cmpFrom = compareRows[0].query_from;
  var cmpTo = compareRows[0].query_to;
  var prev = calcKPIs(compareRows, cmpFrom, cmpTo);

  function makeExplain(currentVal, prevVal, downIsGood) {
    if (prevVal === 0) return "";
    var change = ((currentVal - prevVal) / prevVal) * 100;
    var rounded = Math.abs(Math.round(change * 10) / 10);
    var prevRounded = Math.round(prevVal * 10) / 10;
    if (change < 0) {
      var cls = downIsGood ? "compareup" : "comparedown";
      return "<span class='" + cls + "'>↓" + rounded + "% (was " + prevRounded + ")</span>";
    }
    var cls2 = downIsGood ? "comparedown" : "compareup";
    return "<span class='" + cls2 + "'>↑" + rounded + "% (was " + prevRounded + ")</span>";
  }

  resolved_explain = makeExplain(current.totalResolved, prev.totalResolved, false);
  created_explain = makeExplain(current.createdIssues, prev.createdIssues, true);
  resolution_time_explain = makeExplain(current.medianResolutionTime, prev.medianResolutionTime, true);
  story_points_explain = makeExplain(current.totalStoryPoints, prev.totalStoryPoints, false);
}

var resolvedIssueRows = [];
var openIssueRows = [];
for (var oi = 0; oi < issueRows.length; oi++) {
  var oIssue = issueRows[oi];
  if (oIssue.status === 'TODO' || oIssue.status === 'IN_PROGRESS') {
    openIssueRows.push({
      id: oIssue.issue_key,
      url: oIssue.url || '',
      status: oIssue.status,
      assignee: oIssue.assignee_name || '',
      project: oIssue.original_project || ''
    });
  } else if (oIssue.resolution_date) {
    var oCreated = new Date(oIssue.created_date);
    var oResolved = new Date(oIssue.resolution_date);
    var oHours = (isNaN(oCreated.getTime()) || isNaN(oResolved.getTime())) ? 0 : Math.round((oResolved - oCreated) / (1000 * 60 * 60) * 10) / 10;
    resolvedIssueRows.push({
      id: oIssue.issue_key,
      url: oIssue.url || '',
      resolution_time: oHours,
      project: oIssue.original_project || ''
    });
  }
}
resolvedIssueRows.sort(function(a, b) { return b.resolution_time - a.resolution_time; });

var projectSet = {};
for (var p = 0; p < issueRows.length; p++) {
  var proj = issueRows[p].original_project;
  if (proj) projectSet[proj] = true;
}
var availableProjects = Object.keys(projectSet).sort();

({
  type: "stats",
  availableProjects: availableProjects,
  label: "Key Metrics",
  description: "The key metrics offer a single-figure snapshot of issue tracking for the team. 'Total Resolved Issues' counts issues resolved in the time frame. 'Open Issues' counts issues currently in TODO or IN_PROGRESS status. 'Created Issues' counts issues created during the time frame. 'Median Resolution Time' is the median time from issue creation to resolution. 'Story Points Completed' is the sum of story points for resolved issues.",
  lastupdate: new Date().getTime(),
  data: {
    metrics: [
      { label: "Total Resolved Issues", explain: resolved_explain, value: current.totalResolved },
      { label: "Median Resolution Time (hours)", explain: resolution_time_explain, value: current.medianResolutionTime },
      { label: "Created Issues", explain: created_explain, value: current.createdIssues },
      { label: "Open Issues", value: current.openIssues },
      { label: "Story Points Completed", explain: story_points_explain, value: current.totalStoryPoints }
    ],
    extra: {
      config: [
        {
          location: "appendToAnalytics",
          type: "openList",
          field: "resolved_issues",
          template: "Show Resolved Issues",
          labels: [
            { label: "Issue Key", field: "id" },
            { label: "URL", field: "url" },
            { label: "Resolution Time (hours)", field: "resolution_time" },
            { label: "Project", field: "project" }
          ]
        },
        {
          location: "appendToAnalytics",
          type: "openList",
          field: "open_issues",
          template: "Show Open Issues",
          labels: [
            { label: "Issue Key", field: "id" },
            { label: "URL", field: "url" },
            { label: "Status", field: "status" },
            { label: "Assignee", field: "assignee" },
            { label: "Project", field: "project" }
          ]
        }
      ],
      data: {
        resolved_issues: resolvedIssueRows,
        open_issues: openIssueRows
      }
    }
  }
})
